package com.example.discovery.registry.api;import com.example.discovery.registry.model.*;import com.example.discovery.registry.service.ServiceRegistryService;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/registry/services") public class RegistryController{private final ServiceRegistryService registry; public RegistryController(ServiceRegistryService registry){this.registry=registry;} @PostMapping public ResponseEntity<ServiceInstance> register(@RequestBody RegisterServiceRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(registry.register(request));} @GetMapping public Map<String,List<ServiceInstance>> all(){return registry.findAll();} @GetMapping("/{serviceName}") public List<ServiceInstance> byName(@PathVariable String serviceName){return registry.findByServiceName(serviceName);} @PostMapping("/{serviceName}/{instanceId}/heartbeat") public ServiceInstance heartbeat(@PathVariable String serviceName,@PathVariable String instanceId){return registry.heartbeat(serviceName,instanceId);} @DeleteMapping("/{serviceName}/{instanceId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable String serviceName,@PathVariable String instanceId){registry.deregister(serviceName,instanceId);}}
